  --color-bg: #121212;
  --color-surface: #1e1e1e;
  --color-text: #e0e0e0;
  --color-text-bright: #ffffff;
  --color-text-muted: #b0b0b0;
  --color-accent: #bb86fc;
  --color-accent-hover: #d1adff;
  --color-border: #333333;
  --color-focus-outline: #bb86fc;
  --spacing-base: 1rem;
  --border-radius: 8px;
  --transition-speed: 0.2s;
}

/* Reset and Base Styles */
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
  line-height: 1.6;
}

.container {
  max-width: 800px;
  margin: 0 auto;
  padding: 0 var(--spacing-base);
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: -100px;
  left: 0;
  background: var(--color-accent);
  color: var(--color-bg);
  padding: 0.5rem 1rem;
  z-index: 100;
  text-decoration: none;
  font-weight: bold;
  border-radius: 0 0 4px 0;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--color-bg);
}

/* Header & Footer */
header {
  padding: 2rem 0;
  border-bottom: 1px solid var(--color-border);
}

.site-title {
  margin: 0;
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--color-accent);
}

footer {
  margin-top: 4rem;
  padding: 2rem 0;
  border-top: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.875rem;
  text-align: center;
}

/* Typography */
h1 {
  font-size: 2.5rem;
  color: var(--color-text-bright);
  margin-bottom: 0.5rem;
}

.intro {
  font-size: 1.2rem;
  color: var(--color-text-muted);
  margin-bottom: 3rem;
}

/* FAQ Styles */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.example {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  overflow: hidden;
}

.example h2 {
  margin: 0;
  font-size: 1.1rem;
}

.faq-trigger {
  width: 100%;
  padding: 1.5rem;
  background: none;
  border: none;
  color: var(--color-text-bright);
  text-align: left;
  font-family: inherit;
  font-size: inherit;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background-color var(--transition-speed);
}

.faq-trigger:hover,
.faq-trigger:focus {
  background-color: rgba(255, 255, 255, 0.05);
}

.faq-trigger:focus {
  outline: 2px solid var(--color-focus-outline);
  outline-offset: -2px;
}

/* Arrow icon */
.icon {
  width: 1.25rem;
  height: 1.25rem;
  position: relative;
  transition: transform var(--transition-speed);
  flex-shrink: 0;
  margin-left: 1rem;
}

.icon::before,
.icon::after {
  content: "";
  position: absolute;
  background-color: var(--color-accent);
  transition: transform var(--transition-speed);
}

/* Plus to Minus transition or just an arrow */
.icon::before {
  width: 2px;
  height: 100%;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
}

.icon::after {
  width: 100%;
  height: 2px;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
}

.faq-trigger[aria-expanded="true"] .icon {
  transform: rotate(135deg); /* Turns plus into an X or something else */
}

/* Content panel */
.details {
  padding: 0 1.5rem 1.5rem 1.5rem;
  color: var(--color-text);
  border-top: 1px solid transparent;
}

.faq-trigger[aria-expanded="true"] + .details {
  border-top-color: var(--color-border);
}

[hidden] {
  display: none !important;
}

/* Forced Colors adjustment */
@media (forced-colors: active) {
  .faq-trigger:focus {
    outline: 2px solid ButtonText;
  }
  .icon::before,
  .icon::after {
    background-color: ButtonText;
  }
}
