    trigger.parentElement.parentElement.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const isExpanded = trigger.getAttribute('aria-expanded') === 'true';
        if (isExpanded) {
          trigger.setAttribute('aria-expanded', 'false');
          if (panel) {
            panel.hidden = true;
          }
          trigger.focus();
        }
      }
    });
  });
});
