      <p class="intro">Everything you wanted to know about your mysterious feline friends.</p>

      <div class="faq-list">
        <div class="example">
          <h2>
            <button type="button" aria-expanded="false" class="faq-trigger" id="faq-trigger-1" aria-controls="faq-panel-1">
